import re
from fractions import Fraction

def extract(text):
    m = re.findall(r"\\boxed\{([^{}]*)\}", text)
    if m:
        return m[-1]
    m = re.findall(r"####\s*(-?[\d,./]+)", text)   # GSM8K style
    return m[-1] if m else None

def normalize(s):
    s = s.strip().replace(",", "").replace("$", "").rstrip(".")
    try:
        return Fraction(s)            # "12.0", "0.5", "1/2" all parse
    except (ValueError, ZeroDivisionError):
        return s                      # fall back to the cleaned string

def accuracy_reward(completion, truth):
    ans = extract(completion)
    if ans is None:
        return 0.0
    return 1.0 if normalize(ans) == normalize(truth) else 0.0

def format_reward(completion):
    ok = re.fullmatch(r"(?s).*<think>.+</think>.*\\boxed\{[^{}]+\}\s*", completion)
    return 1.0 if ok else 0.0

if __name__ == "__main__":
    cases = [("x = 12. \\boxed{12}", "12", 1), ("\\boxed{ 12 }", "12", 1),
             ("\\boxed{12.0}", "12", 1), ("so the answer is 12.", "12", 0),
             ("\\boxed{0.5}", "1/2", 1), ("\\boxed{1,200}", "1200", 1),
             ("\\boxed{13}", "12", 0)]
    for c, t, want in cases:
        assert accuracy_reward(c, t) == want, c
    assert format_reward("<think>3 x 4 = 12</think> \\boxed{12}") == 1
    assert format_reward("\\boxed{12}") == 0
    print("all", len(cases) + 2, "reward tests pass")
